  [/^Kết quả: (\d+)\/(\d+) · \+(\d+) XP\. Từ trả lời đúng được đánh dấu là đã nhớ\.$/, "Result: $1/$2 · +$3 XP. Correctly answered words are marked as learned.", "结果：$1/$2 · +$3 XP。答对的词会被标记为已记住。"],
  [/^(\d+) từ đi kèm (\d+) bài luyện nói, đối chiếu (.+)\. Bấm vào từ để nghe phát âm\.$/, "$1 words from $2 speaking lessons, checked against $3. Click a word to hear it.", "$1 个词，来自 $2 节口语课，对照 $3。点击单词即可听发音。"],
  [/^(\d+) từ nên học sau bài này\. Bấm vào từng từ để nghe\.$/, "$1 words to learn after this lesson. Click each word to hear it.", "本课后建议学习的 $1 个词。点击每个词即可收听。"],
  [/^Nhãn cấp độ đối chiếu$/, "Level labels follow", "等级标签参照"],
  [/^Tuần từ (\d+\/\d+\/\d+)( \(tuần này\))?$/, (m, d, cur) => [`Week of ${d}${cur ? " (this week)" : ""}`, `${d} 起的一周${cur ? "（本周）" : ""}`]],
  [/^Đạt ngày (.+)$/, "Earned on $1", "获得于 $1"],
  [/^Đạt ngày (.+?)$/, "Earned on $1", "获得于 $1"],
  [/^Đã đạt (\d+)\/(\d+) thành tựu (tiếng Anh|tiếng Trung)\. Hoàn thành một phần học lớn để nhận cúp vàng, đi được 30% hay 60% để nhận huy chương\. Đổi ngôn ngữ đang học ở trang chủ để xem thành tựu (tiếng Anh|tiếng Trung)\.$/,
    (m, a, b, l1, l2) => [`${a}/${b} ${l1 === "tiếng Anh" ? "English" : "Chinese"} achievements earned. Finish a whole section to win a gold trophy; reach 30% or 60% to earn medals. Switch the language you're learning on the home page to see the ${l2 === "tiếng Anh" ? "English" : "Chinese"} achievements.`,
      `已获得 ${a}/${b} 个${l1 === "tiếng Anh" ? "英语" : "中文"}成就。完成一个大板块可获得金杯，达到 30% 或 60% 可获得奖牌。在首页切换正在学习的语言即可查看${l2 === "tiếng Anh" ? "英语" : "中文"}成就。`]],
  /* tên và mô tả thành tựu */
  [/^Bước đầu (phát âm|giao tiếp cơ bản|giao tiếp công việc|từ vựng)$/, (m, s) => [`First steps: ${I18N.sec(s, 0)}`, `${I18N.sec(s, 1)}起步`]],
  [/^(Phát âm|Giao tiếp cơ bản|Giao tiếp công việc|Từ vựng): (\d+)%$/, (m, s, p) => [`${I18N.sec(s, 0)}: ${p}%`, `${I18N.sec(s, 1)}：${p}%`]],
  [/^Hoàn thành (Phát âm|Giao tiếp cơ bản|Giao tiếp công việc|Từ vựng)$/, (m, s) => [`${I18N.sec(s, 0)} complete`, `完成${I18N.sec(s, 1)}`]],
  [/^Hoàn thành (\d+) (âm|bài|từ) đầu tiên phần (.+) (tiếng Anh|tiếng Trung)$/, (m, n, u, s, l) => [`Complete the first ${n} ${({"âm":"sound","bài":"lesson","từ":"word"})[u]}${n > 1 ? "s" : ""} of ${l === "tiếng Anh" ? "English" : "Chinese"} ${I18N.sec(s, 0)}`, `完成${l === "tiếng Anh" ? "英语" : "中文"}${I18N.sec(s, 1)}的前 ${n} ${({"âm":"个音","bài":"课","từ":"个词"})[u]}`]],
  [/^Đi được (\d+)% phần (.+) (tiếng Anh|tiếng Trung)$/, (m, p, s, l) => [`Reach ${p}% of ${l === "tiếng Anh" ? "English" : "Chinese"} ${I18N.sec(s, 0)}`, `${l === "tiếng Anh" ? "英语" : "中文"}${I18N.sec(s, 1)}完成 ${p}%`]],
  [/^Học xong toàn bộ phần (.+) (tiếng Anh|tiếng Trung)$/, (m, s, l) => [`Finish all of ${l === "tiếng Anh" ? "English" : "Chinese"} ${I18N.sec(s, 0)}`, `学完全部${l === "tiếng Anh" ? "英语" : "中文"}${I18N.sec(s, 1)}`]],
  [/^Bậc thầy (tiếng Anh|tiếng Trung)$/, (m, l) => [`${l === "tiếng Anh" ? "English" : "Chinese"} master`, `${l === "tiếng Anh" ? "英语" : "中文"}大师`]],
  [/^Hoàn thành cả 4 phần: Phát âm, Giao tiếp cơ bản, Giao tiếp công việc và Từ vựng (tiếng Anh|tiếng Trung)$/, (m, l) => [`Complete all 4 ${l === "tiếng Anh" ? "English" : "Chinese"} sections: Pronunciation, Basic conversation, Work conversation and Vocabulary`, `完成全部 4 个${l === "tiếng Anh" ? "英语" : "中文"}板块：发音、基础会话、职场会话和词汇`]],
  [/^Thành tựu (tiếng Anh|tiếng Trung)$/, (m, l) => [`${l === "tiếng Anh" ? "English" : "Chinese"} achievements`, `${l === "tiếng Anh" ? "英语" : "中文"}成就`]],
  /* pomodoro, lịch */
  [/^Học (\d+) phút, nghỉ (\d+) phút\. Cứ (\d+) lượt học thì nghỉ dài (\d+) phút\.$/, "Study $1 min, break $2 min. Every $3 sessions, take a long $4-min break.", "学习 $1 分钟，休息 $2 分钟。每 $3 轮学习后长休息 $4 分钟。"],
  [/^Hôm nay bạn đã học (\d+) lượt\.$/, "You've done $1 sessions today.", "今天你已学习 $1 轮。"],
  [/^(\d+) lần$/, "$1×", "$1 次"],
  [/^(\d+) việc chưa xếp ngày$/, "$1 unscheduled tasks", "$1 项未安排日期的待办"],
  [/^Tháng (\d+)(,? \d+)?$/, (m, a, y) => [["January","February","March","April","May","June","July","August","September","October","November","December"][a - 1] + (y || ""), (y ? y.replace(/\D/g, "") + "年" : "") + a + "月"]],
  [/^Chưa tìm thấy bài nào khớp với “(.+)”\. Thử từ khác, ví dụ: khách sạn, phỏng vấn, ngân hàng, \/æ\/, 你好\.$/, "No lessons match “$1”. Try another word, e.g. hotel, interview, bank, /æ/, 你好.", "没有找到与“$1”匹配的课程。换个词试试，例如：酒店、面试、银行、/æ/、你好。"],
  [/^Máy của bạn chưa có giọng đọc (.+)\. Hãy thêm giọng (.+) trong cài đặt ngôn ngữ của điện thoại hoặc máy tính, hoặc mở trang bằng Chrome\.$/, "Your device has no $1 voice. Add a voice in your phone or computer's language settings, or open this page in Chrome.", "你的设备没有$1朗读声音。请在手机或电脑的语言设置中添加，或用 Chrome 打开本页面。"]
